let lang = 'de';
export const setLang = (l) => { lang = l === 'en' ? 'en' : 'de'; document.documentElement.lang = lang; };
export const getLang = () => lang;
export function t(key, vars) {
  const d = lang === 'en' ? EN : DE;
  let s = d[key] ?? DE[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
  return s;
}
/** Text eines zweisprachigen Objekts { de, en }. */
export const tt = (obj) => (obj ? (obj[lang] ?? obj.de ?? '') : '');
export const DICT = { DE, EN };
